import { Button, Modal, Space, Tabs } from "@arco-design/web-react";
import { IconCopy, IconDelete, IconDriveFile, IconMobile, IconToRight } from "@arco-design/web-react/icon";
import React, { useEffect, useMemo, useState } from "react";
import styles from './index.module.less';
import { MyErrorBoundary } from "@/components/custom";
import { dynamicCreateModule } from "@/environments/hoc";
import MobileView, { MobileStore } from '../../mobile/view';
import PageStore from '../../store';
import { moduleStore } from "react-converter-code";

interface PreviewRightProps {
    pageStore: PageStore;
    text: string;
    onClose: () => void;
}

let timer = null;
const PreviewRight = ({ pageStore, text, onClose }: PreviewRightProps) => {

    const [isMobile, setIsMobile] = useState(false);
    const [store] = useState(() => new MobileStore(pageStore));

    const PageElement = useMemo(() => {
        store.setText(text);
        if(text){
            return dynamicCreateModule(text);
        }
        return (props) => <span></span>;
    },[text, isMobile])

    const [visible, setVisible] = useState(false);

    useEffect(() => {
        const timer = setTimeout(() => {
            pageStore.setPreviewImg();
        },5000)
        return () => {
            clearTimeout(timer);
        }
    }, [PageElement])
    

    return (
        <React.Fragment>
            {!visible? (
                <div style={{ height: '100%', display: "flex", flexDirection: "column" }}>
                    <Tabs type="card"
                        extra={
                            <Space>
                                <Button type="text" icon={<IconDriveFile />} >
                                    { pageStore.name }
                                </Button>
                                <Button
                                    onClick={() => {
                                        setVisible(true)
                                    }} 
                                    size='small' type='primary' icon={<IconCopy />}
                                />
                                <Button
                                    size="small"
                                    type={isMobile? "primary" : "default"}
                                    icon={<IconMobile style={{ marginRight: 0 }} />}
                                    onClick={() => {
                                        setIsMobile(!isMobile)
                                    }}
                                />
                                <Button
                                    onClick={() => {
                                        onClose();
                                    }}
                                    icon={<IconDelete />}
                                />
                            </Space>
                        }
                    >
                        <Tabs.TabPane key='1' title='预览'>
                        </Tabs.TabPane>
                    </Tabs>
                    <div className={styles.pageRight} id={pageStore.previewId}>
                        <MobileView store={store} isMobile={isMobile} />
                    </div>
                </div>
            ) : (
                <Modal
                    title={
                        <div style={{ marginRight: 30, display: 'flex', alignItems: 'center', justifyContent: "space-between" }}>
                            <span>
                                预览
                            </span>
                            <Space>
                                <Button
                                    size="small"
                                    type={isMobile? "primary" : "default"}
                                    icon={<IconMobile style={{ marginRight: 0 }} />}
                                    onClick={() => {
                                        setIsMobile(!isMobile)
                                    }}
                                />
                                <Button
                                    size="small"
                                    type="default"
                                    icon={<IconToRight />}
                                    onClick={() => {
                                        setVisible(false)
                                    }}
                                />
                            </Space>
                        </div>
                    }
                    visible={true}
                    className={`${styles.modal} ${styles.fullscreen} arco-modal-page-html`}
                    footer={null}
                    maskClosable={false}
                    onCancel={() => {
                        onClose()
                    }}
                >
                    <div id={pageStore.previewId} className={styles.preview}>
                        <MobileView store={store} isMobile={isMobile} />
                    </div>
                </Modal>
            )}
        </React.Fragment>
    )
}


export default PreviewRight;